def task(exc):
    raise exc()

for exc in (ValueError, SystemExit, KeyboardInterrupt):
    try:
        try:
            task(exc)
        except Exception:                 # catches normal errors only
            print("except Exception caught", exc.__name__)
    except BaseException as e:            # outer net, to keep the demo running
        print("escaped except Exception:", type(e).__name__)

