    print("bare except swallowed Ctrl+C")  # the program could not be stopped

import pickle

class PaymentError(Exception):
    """Base class: callers can catch everything from this package."""

class InvalidAmountError(PaymentError, ValueError):   # fits both families
    pass

class CardDeclinedError(PaymentError):
    def __init__(self, amount, reason):
        super().__init__(amount, reason)    # keep args == constructor args
        self.amount = amount
        self.reason = reason
    def __str__(self):
        return f"card declined for {self.amount}: {self.reason}"

class BadPickle(Exception):
    def __init__(self, amount, reason):
        super().__init__(f"{amount} {reason}")   # args no longer match

def pay(amount):
    if amount <= 0:
        raise InvalidAmountError("amount must be positive")
    raise CardDeclinedError(amount, "insufficient funds")

for amt in (-5, 30):
    try:
        pay(amt)
    except PaymentError as e:                 # one clause for the package
        print(type(e).__name__, "->", e, "| is ValueError:", isinstance(e, ValueError))

copy = pickle.loads(pickle.dumps(CardDeclinedError(30, "limit")))
print("pickle round trip:", copy, copy.amount)
try:
    pickle.loads(pickle.dumps(BadPickle(1, "x")))
except TypeError as e:
    print("unpickling failed:", type(e).__name__)

def low():
    return {}["k"]                      # raises KeyError

def implicit():
    try:
        low()
    except KeyError:
        raise RuntimeError("looks like a bug in the handler")

def explicit():
    try:
        low()
    except KeyError as e:
        raise RuntimeError("deliberate translation") from e

def hidden():
    try:
        low()
    except KeyError:
        raise RuntimeError("low-level noise hidden") from None

for f in (implicit, explicit, hidden):
    try:
        f()
    except RuntimeError as e:
        print(f.__name__)
        print("  cause:   ", repr(e.__cause__))
        print("  context: ", repr(e.__context__))
        print("  suppress:", e.__suppress_context__)

try:
    try:
        low()
    except KeyError as e:
        e.add_note("while loading config")   # Python 3.11+
        raise
except KeyError as e:
    print("notes:", e.__notes__)

def lbyl(s):
    if s.isdigit():                # look before you leap
        return int(s)
    return None

def eafp(s):
    try:
        return int(s)              # the real operation is the check
    except ValueError:
        return None

for s in ["42", "-7", "abc", "²"]:   # last one is superscript two
    try:
        a = lbyl(s)
    except ValueError as e:
        a = "CRASH " + str(e)
    print(repr(s), "LBYL:", a, "| EAFP:", eafp(s))

