from typing import Any

def shout_any(x: Any):
    return x.upper()              # checker allows anything on Any

def shout_obj(x: object):
    # a checker rejects x.upper() here until x is narrowed
    if isinstance(x, str):
        return x.upper()          # narrowed to str: allowed
    return str(x)                 # str() works on every object

for v in ["hi", 5]:
    print(repr(v), "->", shout_obj(v))

try:
    shout_any(5)                  # the checker said nothing
except AttributeError as e:
    print("Any hid the bug until runtime:", e)

import sys
import unittest

def parse_age(s):
    n = int(s)
    if n < 0:
        raise ValueError("age must not be negative")
    return n

class ParseAgeTests(unittest.TestCase):
    def test_valid(self):
        for text, want in [("0", 0), ("41", 41), ("120", 120)]:
            with self.subTest(text=text):          # each case reported alone
                self.assertEqual(parse_age(text), want)

    def test_negative_message(self):
        with self.assertRaisesRegex(ValueError, "must not be negative"):
            parse_age("-1")                        # checks type and message

    def test_not_a_number(self):
        with self.assertRaises(ValueError):
            parse_age("abc")

suite = unittest.defaultTestLoader.loadTestsFromTestCase(ParseAgeTests)
result = unittest.TextTestRunner(stream=sys.stdout, verbosity=2).run(suite)
print("all passed:", result.wasSuccessful())

from unittest import mock

class Repo:
    def save(self, name, email):
        raise NotImplementedError

class FakeRepo:                          # in-memory fake: real behaviour
    def __init__(self):
        self.rows = {}
    def save(self, name, email):
        self.rows[name] = email

def register(repo, name, email):
    repo.save(name, email)
    return "registered " + name

# Style 1: fake. The test checks the outcome, so a refactor does not break it.
fake = FakeRepo()
print(register(fake, "ada", "ada@example.com"), fake.rows)

# Style 2: autospec mock. It only checks that the call was made.
spy = mock.create_autospec(Repo, instance=True)
register(spy, "bob", "bob@example.com")
spy.save.assert_called_once_with("bob", "bob@example.com")
print("mock saw the call:", spy.save.call_args)

# autospec rejects calls that do not match the real signature
try:
    spy.save("only-one-argument")
except TypeError as e:
    print("autospec caught a wrong call:", type(e).__name__)

import random

def retry(fn, attempts, sleep, rng):
    delay = 0.1
    for i in range(attempts):
        try:
            return fn()
        except ConnectionError:
            if i == attempts - 1:
                raise
            sleep(delay + rng.random() * 0.01)   # jitter from injected rng
            delay *= 2                           # exponential backoff

def make_flaky(failures):
    state = {"calls": 0}
    def fn():
        state["calls"] += 1
        if state["calls"] <= failures:
            raise ConnectionError("down")
        return "ok after %d calls" % state["calls"]
    return fn

def run(seed):
    slept = []
    result = retry(make_flaky(2), 5, slept.append, random.Random(seed))
    return result, [round(s, 4) for s in slept]   # fake sleep records delays

first = run(42)
print("result and delays:", first)
print("same seed, same run:", run(42) == first)   # deterministic and instant

def validate(order):
    errors = []
    if order["qty"] <= 0:
        errors.append(ValueError("qty must be positive"))
    if not order["email"]:
        errors.append(KeyError("email"))
    if order["qty"] > 100:
        errors.append(ValueError("qty too large"))
    if errors:
        raise ExceptionGroup("invalid order", errors)   # report every problem

order = {"qty": 0, "email": ""}
print("order:", order)
try:
    validate(order)
except* ValueError as eg:           # gets a sub-group of the ValueErrors
    print("ValueErrors:", [str(e) for e in eg.exceptions])
except* KeyError as eg:             # the remaining ones go here
    print("KeyErrors:", [repr(e) for e in eg.exceptions])

try:
    validate(order)
except ValueError:                  # plain except does not match a group
    print("never printed")
except Exception as e:
    print("plain except sees:", type(e).__name__, len(e.exceptions), "errors")
